use std::collections::HashSet;

/// Elements of `a` that also appear in `b`, preserving a's order/duplicates.
/// BUG: `b.contains(&x)` is a linear scan, so this is O(n*m) - unusably slow
/// for large slices. Membership should be O(1) via a HashSet.
#[allow(unused_imports)]
pub fn common(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::new();
    for &x in a {
        if b.contains(&x) {
            out.push(x);
        }
    }
    out
}

test_setup_files.tests/intersection_test.rs:
use intersection_perf::common;
use std::collections::HashSet;
use std::time::Instant;

#[test]
fn correctness_and_performance() {
    assert_eq!(common(&[1, 2, 3, 4], &[2, 4, 6]), vec![2, 4]);
    // order and duplicates of `a` preserved
    assert_eq!(common(&[5, 1, 5, 9, 1], &[1, 5]), vec![5, 1, 5, 1]);
    assert_eq!(common(&[], &[1, 2]), Vec::<i32>::new());
    assert_eq!(common(&[1, 2, 3], &[]), Vec::<i32>::new());

    // Large input: an O(n*m) scan blows past the budget; an O(n) HashSet
    // membership check finishes almost instantly. Timed with Instant so the
    // failure is a clear assertion, not an ambiguous process timeout.
    let n = 30_000i32;
    let a: Vec<i32> = (0..n).map(|i| i * 3).collect();
    let b: Vec<i32> = (0..n).map(|i| i * 7).collect();

    let set: HashSet<i32> = b.iter().copied().collect();
    let expected: Vec<i32> = a.iter().copied().filter(|x| set.contains(x)).collect();

    let start = Instant::now();
    let got = common(&a, &b);
    let elapsed = start.elapsed();

    assert_eq!(got, expected, "large-input intersection result is incorrect");
    assert!(
        elapsed.as_secs_f64() < 1.5,
        "common took {:?} for n={} (looks like still O(n*m)); expected an O(n) HashSet membership check",
        elapsed,
        n
    );
}

